#
# 素直な IPA。アクセントは母音の上の記号ではなく独立した記号で書くので、
# ここには同じ字の重複がない: /ˈmjuːzɪk/、/ˈfɑːðə/、/θɪŋk/、/kæt/、/bɜːd/、
# /ɡəʊ/。これらで裏を取った。
