    # そして ½ もない。ディスクは 10 か所のうち 9 か所で、½ が来るべき場所に
    # ¼ を置いている——letter-size の 8½ × 11 インチ、tropic の 23½°、
    # half の 「Three halves make 1½」——そして 10 番目、year の 365¼ 日だけは
    # 正しい。本自身の使い方が割れている以上、字形のほうを採る。これは描かれて
    # いるとおりの 4 分の 1 であり、½ のほうはこちらではなくディスクの誤りである。
    # 先頭に空白を入れてあるのは、分数が本では 1 字、ここでは 3 文字になるから。
