# 符号 5 つと 2 つで、この本の全 71,258 出現のうち 67,952 を占める。
# アクセントは ┏ と ┓ で示されるが、これはふつうの JIS 文字なので対応表は要らない。
#
# その 7 つの裏には、アクセント付きラテン文字のフォントがひと揃いある。並びは
# 文字順ではなくアクセント順で、母音全部にアキュート、次に母音全部にグレーブ、
# 続いてトレマ、サーカムフレックス、マクロン、ブレーヴェ、ハーチェク、
# オゴネク、セディーユ、下点、上点、上輪。各組はアクセントの位置をずらして
# 2、3 回描かれている——0xa138、0xa144、0xa153 の Á は同じ文字を 3 通りに
# 詰めたもの——ので、1 組読めばその写しも全部決まる。どの組も同じ 2 字で
# 終わるが、それは文字ではなく IPA の ʌ と ø である。ハフダフ が
# [hʌf dʌf] と出るのはそのためだ。
