#
# 半角 29 字、全角 14 字——手元でいちばん小さいフォントであり、いちばん
# 働いているフォントでもある。全角のうち 2 字が全 371,517 出現の 99.8% を
# 占める。用例はすべて 「→〈矢印〉」 で終わって見出し語に戻り、見出し行は
# すべて 「→〈開いた本〉」 で終わって記事本体を指す。この 2 つの案内用の
# アイコンが、用例ごとに 1 回、項目ごとに 1 回描かれるわけだ。
#
# 半角フォントは、この本がフランス語・スペイン語の引用に必要とする
# アクセント付きラテン文字と、短い IPA の並び。すべて、それが何かを言葉で
# 述べている文と突き合わせて確かめた: ɑ̃ と ɛ̃ には 鼻母音、iː には 前舌母音、
# アスタリスクには 星印、ダブルハイフンには ダブルハイフン。このアスタリスク
# は一言添えておく価値がある。16 画素と 30 画素では単なる + に潰れてしまい、
# 本文が語っている 6 本の線を描いているのは 24 画素と 48 画素のフォントだけ
# である。
#
# 全角フォントは JIS X 0208 にない漢字 7 字——どれも、それを使う項目が意味を
# 説明してくれる（嗉嚢、尾骶骨、炻器、有稃種）——といくつかの記号。
