# ---------------------------------------------------------------------------
# ジーニアス英和・和英辞典 (大修館書店, EPWING)
#
# 字形 199、うち使用は 185。新グローバル と同じくこの本も 発音記号表 を
# 載せており、同じく半角フォントと全角フォントが 0xa121..0xa235 を共有して
# いるので、1 度読めば両方が決まる。ここにあるもののほとんどはアクセント記号を
# 載せた母音である。この辞書はアクセントを音節の前ではなく文字の上に付ける
# からだ: táble knífe、Jápanèse、unháppy。そのアルファベットを 2 回——本文用と、
# 見出し語用の太字で——描いており、だから á が 0xa121 と 0xa155 の両方にある。
#
# 手元の全ディスクを通じていちばん働いている字形がここにある。発音を開いて
# 閉じるスラッシュで、91,698 回、この本の外字の 5 分の 1 以上を占める。
# ---------------------------------------------------------------------------
GENIUS: GaijiTable = {
    **both({
        # この本が見出し語を書くのに使う、アクセント付きラテン文字。
        # 本文用の書体で 1 組、続いて見出し語用の書体でもう 1 組。
        **run(0xA121, ["á", "à"]),
        **run(0xA12E, ["é", "è"]),
        **run(0xA134, ["í", "ì"]),
        **run(0xA136, ["ó", "ò", "ō", "ö"]),
        **run(0xA13E, ["ú", "ù"]),
        **run(0xA155, ["á", "à", "é", "è", "í", "ì", "ó", "ò", "ú", "ù"]),

        # 発音記号表 の母音。それぞれにアクセント記号 2 種と、フランス語に
        # 必要なところには鼻音のチルダが付く: /ɑː/ father、/ʌ/ cup、
        # /ə/ collect、/əː(r)/ bird、/ɔː/ law、/ɚ/ 鉤付きシュワー、/æ/ bat。
        **run(0xA123, ["ɑ", "ɑ́", "ɑ̀", "ɑ̃"]),
        **run(0xA127, ["ʌ", "ʌ́", "ʌ̀"]),
        **run(0xA12A, ["ə", "ə́", "ə̀"]),
        # 同じシュワーを斜めにしたもの。ある国では発音され、別の国では
        # 発音されないことを、この本はこう示す: /-iər-/ は 米 では /-ir-/。
        (True, 0xA12D): "ə",
        **run(0xA130, ["ɜ", "ɜ́", "ɜ̀", "ɜ̃"]),
        **run(0xA13A, ["ɔ", "ɔ́", "ɔ̀", "ɔ̃"]),
        **run(0xA140, ["ɚ", "ɚ́", "ɚ̀"]),
        **run(0xA143, ["æ", "ǽ", "æ̀", "æ̃"]),
        **run(0xA147, ["œ", "œ̃"]),

        **run(0xA149, ["ɡ", "ŋ", "θ", "ð", "ʃ", "tʃ", "r", "ɔɪ", "ø", "ʒ",
                       "dʒ", "ː"]),

        # ダッシュは上の発音の音節を表し、その音節のアクセントを載せる:
        # 《◆限定用法では通例／−́−̀／》。
        (True, 0xA15F): "−́", (True, 0xA160): "−̀",
        (True, 0xA161): "ç", (True, 0xA162): "ç",

        # 大文字と、残りのアクセント付きラテン文字。それらを印刷している語から
        # 読んだ: Ádam and Éve、Ènglish、Ý chrómosome、B́ báttery、Dvořák、
        # Boötes、Curaçao、Köchel、cāme と bē。
        **run(0xA16A, ["Á", "À", "Ć", "É", "Ó", "Ò", "Ô", "ý", "ỳ", "Ý", "B́",
                       "ë", "Í", "È", "Ù", "Ì", "ä", "ř", "ï", "Ú", "i"]),
        **run(0xA221, ["ü", "ā", "ē", "î", "â", "ã", "ñ", "ê"]),
        (True, 0xA229): "*",        # 省略符号《．．．，***，など》
        (True, 0xA22A): "ö",
        # 子音の下の輪は無声であることを示す: umph /m̥m̥/。
        (True, 0xA22B): "m̥", (True, 0xA22D): "n̥", (True, 0xA22F): "p̥",
        # 記号だけを描いたもの。どれもそれを印刷している項目が名前を
        # 挙げている: 長音符号、ティルデ、短音記号、セディーユ、
        # スタッカート、小点。
        (True, 0xA22C): "◌̄", (True, 0xA22E): "◌̃", (True, 0xA230): "◌̆",
        (True, 0xA231): "◌̧", (True, 0xA232): "▾", (True, 0xA234): "◌̇",
        (True, 0xA233): "Ḱ",

        (True, 0xA235): "/",        # すべての発音を開き、閉じる
    }),

    (False, 0xA421): "⇨",       # …を見よ
    (False, 0xA422): "⛤",       # 星形五角形《魔術の記号》
    (False, 0xA423): "卌", (False, 0xA45D): "𝍸",   # 「正」の字に相当する印
    (False, 0xA426): "〜",       # 波線《〜〜〜》
    (False, 0xA427): "＞", (False, 0xA428): "＜",  # 〔音〕増減記号
    (False, 0xA429): "卐",       # まんじ《卍，卐など》

    # 名詞の数えかたと、動詞・形容詞の性質——〖S〗 状態性 と 〖D〗 動作性 の
    # 対で、この本が 世界で初めての試み と称しているもの。
    (False, 0xA430): "〖C〗", (False, 0xA431): "〖U〗",
    (False, 0xA432): "〖S〗", (False, 0xA433): "〖D〗",

    # イントネーション。声の描く曲線として描かれ、凡例 に名前がある:
    # 下降上昇調、上昇調、下降調、部分下降調。
    (False, 0xA434): "⌄", (False, 0xA435): "⤴",
    (False, 0xA436): "⤵", (False, 0xA437): "⤹",
    (False, 0xA43B): "|",       # イントネーション句の切れ目

    # 複合語の中で見出し語の代わりに立つ波ダッシュ。その複合語自身の
    # アクセントを載せる: table の項目にある 〜́ knífe。
    (False, 0xA438): "〜́", (False, 0xA439): "〜̀",
    (False, 0xA43A): "▬",       # 各 品詞 の頭に置かれる黒い罫
    (False, 0xA43E): "ʽ",       # （ギリシア語の）気息音符
    (False, 0xA43F): "⁂", (False, 0xA444): "⁂",   # ３つ星印
    (False, 0xA440): "©",
    (False, 0xA443): "...",     # a bìt of a ... の ...
    (False, 0xA445): "✓",       # 照合［チェック］の印
    (False, 0xA449): "‸",       # （校正用の）挿入記号
    (False, 0xA44D): "V",       # 眼鏡堡《V形に突き出た堡塁》
    (False, 0xA44E): "♮",       # 本位記号
    (False, 0xA44F): "𝄐", (False, 0xA450): "𝄑",   # フェルマータ
    (False, 0xA451): "(R)",
    (False, 0xA452): "//",      # 参照符号《＊†‡§//¶など》
    (False, 0xA453): "𝄇",       # 反復記号
    (False, 0xA457): "$",
    (False, 0xA458): "𝄫", (False, 0xA45A): "𝄪",   # ダブルフラット, ダブルシャープ
    (False, 0xA459): "ς",
    (False, 0xA45F): "#",       # ♮ や 𝄪 と違い ♯ は曖昧幅

    # 語義を大きく区分する丸数字。①..㉑ は東アジア曖昧幅。
    **run(0xA460, [f"({n})" for n in range(1, 22)], narrow=False),

    # JIS X 0208 にない漢字。どれもその字自身の注記から読んだ:
    # 鬐甲（きこう）、槊杖（さくじょう）、瘙痒症、刺胳（しらく）、癤（せつ）、
    # 蒴（さく）、瘭疽（ひょうそ）、翮（かく）、煆焼、灌木、尾骶骨、
    # 駃騠（けってい）、枘（ほぞ）、嗉嚢（そのう）、炻器、絇（こ）、
    # 鱓（うつぼ）。
    **series("""
        a424 鬐   a42a 槊   a42b 瘙   a42c 胳   a42e 癤   a42f 蒴   a43d 瘭
        a441 翮   a442 煆   a447 灌   a44a 骶   a44b 駃   a44c 騠   a454 枘
        a456 嗉   a45b 炻   a45c 絇   a45e 鱓
    """),

    # 「（水鳥の）水かき；羽板，翈（こう）」。新グローバル も自分の持つ同じ
    # 字形に同じ注記を与えている。どちらの本も 甲 を 羽 の左に描いているが、
    # Unicode では左右が逆である。
    (False, 0xA425): "翈",

    # 合字: 合字，抱き字《ｆｉ，ﬂ など》。
    (False, 0xA42D): "ﬂ",

    # 見送ったもの。どれも 1 回きりで、どれも Unicode に対応する文字がない:
    # 0xa448 の 削除記号（輪を描くデリータ）、0xa455 の屋根のない根号
    # （root の項目が √ のより一般的な書き方として挙げているもの）、
    # そして 0xa446 の ♣（他のスートと同じく東アジア曖昧幅）。
}

