# ---------------------------------------------------------------------------
# 広辞苑　第四版　電子ブック版 (岩波書店, EB)
#
# 第四版の半角フォントは第五版と同じものである。0xa121 から
# á à â ä ã ā ạ … ź ẓ と、1 字ずつ一致し、アルファベットの先にある文字も
# 同じ符号に載っている。この本の半角 128 字のうち 79 字は第五版の表がすでに
# 答えを持っているので、そのまま引き継ぐ。
#
# 版が分かれるのは括弧類である。第五版が 〘品詞〙 や [一] や [1] を 1 字形で
# 描くところを、第四版は括弧の 1 つ 1 つを独立した字として描く。だから
# 1 組の符号だけで 17,919 回ずつ使われているし、表がなければここは何ひとつ
# 読めない。
# ---------------------------------------------------------------------------
KOJIEN_4: GaijiTable = {
    **{key: value for key, value in KOJIEN_5.items() if key[0]},

    # 括弧。入れ子の順に: 〘代〙 が品詞、[一] が大区分、[1] が語義、
    # (アイキョウ) は漢字だけでは読みが分からない見出し語に添える読み。
    (False, 0xA43B): "〘", (False, 0xA43C): "〙",
    (True, 0xA225): "[", (True, 0xA226): "]",
    (True, 0xA227): "[", (True, 0xA228): "]",
    (True, 0xA229): "(", (True, 0xA22A): ")",
    # ……そして単独で立つラベル: [季・春]、[参照]、[表]。
    (True, 0xA23B): "[", (True, 0xA23C): "]",

    (False, 0xA43E): "=>",    # ⇒。「…を見よ」
    (False, 0xA421): "<->",   # ↔。「…に対して」
    (False, 0xA460): "->",    # 黒い矢印。->[参照] を指す
    (False, 0xA422): "[文]",  # 文語の見出し語に付く、枠に入った 文
    (False, 0xA43D): "(C)",

    # 繰り返し記号。1 字の繰り返しが 〻、2 字が 〳〵、繰り返す側が濁るときは
    # 〴〵——射たり〳〵、はべしやうしか〴〵。
    (False, 0xA426): "〻",
    (False, 0xA424): "〳", (False, 0xA423): "〵", (False, 0xA43A): "〴",

    # ローマ数字。この本は酸化数——ヘキサ‐アクア‐クロム(III)イオン——と
    # ホルモンの番号に使う: アンギオテンシンII。
    (False, 0xA44B): "I", (False, 0xA44C): "II", (False, 0xA437): "III",
    (False, 0xA441): "IV", (False, 0xA44F): "VI",

    # JIS X 0208 にない漢字。第五版が何百字も必要とするのに対し、第四版が
    # 必要とするのは 30 字あまりで、しかもそのすべてを第五版も描いている。
    **series("""
        a425 蒴   a427 栲   a428 枘   a429 榱   a42a 栬   a42b 垜   a42c 桛
        a42d 糝   a42e 佾   a42f 埵   a430 挵   a431 顥   a432 癭   a433 絓
        a434 閩   a436 窠   a438 鉸   a439 噦   a43f 鏁   a440 邌   a442 俏
        a443 鵼   a444 穭   a445 捥   a446 麞   a447 橅   a448 鄧   a44a 噯
    """),

    (False, 0xA450): "卍",
    (False, 0xA459): "(公)",    # 丸公。戦時の公定価格の印
    (False, 0xA456): "[Gマーク]",
    (False, 0xA457): "[JAS]",
    (False, 0xA45A): "[JIS]",
    (False, 0xA45B): "|",       # 縦の画。画そのものとして挙げられている
    (False, 0xA45D): "ς",
    (False, 0xA45F): "->",

    # 発音記号。音の作り方を説明している項目から: 硬口蓋音 の
    # 〔c〕〔ɟ〕〔ɲ〕 と、シ を作る無声摩擦音 〔ʃ〕。
    (True, 0xA160): "ʃ", (True, 0xA164): "ɟ", (True, 0xA167): "ɲ",

    # アルファベットの並びに入っていない大文字。どれも固有名詞から:
    # Ānanda、Ögedei、Ürgench、Émile、Ångström、Île de la Cité、Łódź、Æsop。
    (True, 0xA177): "Ā", (True, 0xA173): "Ö", (True, 0xA176): "Ü",
    (True, 0xA17E): "É", (True, 0xA171): "Á", (True, 0xA224): "Å",
    (True, 0xA17A): "Î", (True, 0xA17B): "Ł", (True, 0xA17C): "Æ",
    (True, 0xA23D): "å",

    (True, 0xA172): "φ",    # 円柱座標の角
    (True, 0xA17D): "ℏ",    # プランク定数を 2π で割ったもの
    (True, 0xA236): "'",    # 2 本目の直線 l′ のプライム
    (True, 0xA22C): "->",   # ベクトル (OP) の上に書く矢印

    # 見送ったもの: 0xa16f、0xa170、0xa178、0xa179 の根号——√ も ∛ も東アジア
    # 曖昧幅で、しかも根号として読める代役がない。合わせて 6 出現。
}

