# 改訂新版 ことわざ・名言の泉 (EB)
#
# この 3 つは項目の頭に置かれ、その項目の種類を示す。珍しいことに、ここでは
# 字形からではなく、何を導いているかから名前を決めた。この本には 16 画素の
# フォントしか入っておらず、丸の内側に残るのは 12×12 ほど——中の文字を読むには
# 足りない。項目全体を見渡すと、使い分けは一貫している:
#
#   0xa121  ことわざ本体。振り仮名と語釈つき
#   0xa122  日本の作品からの引用——*兼好『徒然草』
#   0xa123  中国の作品からの引用——【『漢書』賈誼伝】後漢
# ---------------------------------------------------------------------------
# ---------------------------------------------------------------------------
# ブリタニカ小項目事典 (TBS ブリタニカ, EB)
#
# 載せる固有名詞をすべてローマ字化する百科事典なので、79,948 ある外字の
# ほとんどが翻字用である。作りが変わっていて、知っておく価値がある:
# **アクセント記号を独立した文字として、かかる文字のうしろに置いて描く**
# ——Åland は A ＋ 上輪、Aydınoğulları は g ＋ ブレーヴェ——これはまさに
# Unicode の結合文字そのものである。だからアクセント記号は完璧に対応づく
# し、結合文字なので曖昧幅の規則の対象外にもなる。
#
# 残りは上付き・下付きのアルファベットで、この順に並ぶ: C D H I K N
# P R S V W X Z a b c e f g i k m n p q r s t y z 0-9、続いて ( ) + ∞ と
# ギリシア文字。数式を載せる本には要るものだ——km2、cm-1、I3、
# 3Rx2ex/(ex-1)2——が、Unicode の上付き数字は曖昧幅なので、全部そのままの
# 文字として出す。どのみち数式は ASCII でもそう読まれる。
#
# 全角フォントは 62 字で 0xa15e で終わっているのに、この本はそれよりずっと
# 先まで全角のエスケープを書いている——0xa15f 以降に全角で来る符号はすべて、
# 組版者が半角の切り替えを入れ忘れた半角記号なので、`leaked()` で両方の
# フォントに渡す。0xa15e より前では、同じ誤りが本物の字形と衝突する
# （μ0 は下付きの 0 を、濊 は漢字を求めていて、どちらも 0xa14b）。そこでは
# 全角のほうを採る。ディスクが実際に描いているのはそれだし、漢字のほうは
# 固有名詞、下付き数字のほうは常に数式の中だからである。
# ---------------------------------------------------------------------------
