# ---------------------------------------------------------------------------
# 角川類語新辞典 (EPWING)
#
# 全角 112 字、半角は数えるほどもない。類語辞典は語を意味で束ねるので、
# JIS X 0208 の外に必要になるのは、その語を「正しく」書くための漢字である
# ——杮落とし の 杮（柿 ではない）、眼窠、風丰、臨摹。
#
# 手元でいちばん読み解きやすい本でもある。書式そのものが答えを教えて
# くれるからだ。項目はすべて 【漢字】かな の形をしており、見出しが綴れない
# ときは代わりに語釈の横に読みを印刷する。だから 「【X纈】ろうけつ」 は
# X が 﨟 だと言い、「〈X蜩〉…かなかなぜみ」 は X が 茅 だと言う。
# ---------------------------------------------------------------------------
RUIGO: GaijiTable = {
    # 用法注記の中の番号付きの項: ①国家・公共団体が…、②各種の法人が…
    **run(0xA177, ["(1)", "(2)", "(3)", "(4)", "(5)", "(6)"], narrow=False),
    (False, 0xA121): "(C)", (False, 0xA17D): "(C)",

    **series("""
        a122 蕺   a173 矻
        a123 腊   a126 遡   a127 枹   a128 胼   a129 壔   a12a 凜   a12b 蔞
        a12c 鰧   a12d 摹   a12e 蘖   a12f 槲   a130 跑   a131 蟖   a132 簒
        a134 捥   a135 﨟   a136 玆   a137 釃   a138 迸   a139 踠   a13a 橅
        a13b 炷   a13c 螈   a13d 瑇   a13e 挵   a13f 吽   a140 噯   a141 鱵
        a142 蛉   a143 蒴   a144 擤   a145 蜱   a146 翟   a147 鼯   a148 櫁
        a149 蠆   a14a 偓   a14b 蘞   a14c 蘩   a14d 噦   a14e 稭   a14f 茅
        a152 驎   a153 鱏   a154 獱   a155 魹   a156 橐   a157 攛   a158 孒
        a159 眴   a15a 鼴   a15b 蠊   a15c 碼   a15e 丰   a15f 窠   a160 搢
        a161 瘭   a162 痎   a163 杮   a164 癎   a165 顬   a166 鱓   a167 咤
        a169 榱   a16a 腔   a16b 艾   a16c 玢   a16d 麬   a16e 糝   a16f 縕
        a170 鱲   a171 梲   a172 顖   a174 簎   a175 裑   a17e 湑
        a122 蕺   a173 矻   a168 痟   a125 渴
    """),
    # 「「い」を「𛀇」と書く類」——変体仮名 の項目が示している 変体仮名。
    # Unicode に収録されているのは 4 つで、これは 伊 の形、崩した 尹 の左に
    # 亻 を下ろしたもの。
    (False, 0xA176): "\U0001B007",

    # 見送ったもの: 0xa124。その項目には読みがまったく印刷されていない。
}

# ---------------------------------------------------------------------------
# 電子ブック版『日本大百科全書』 (小学館, EB)
#
# 字形 384、うち使用は 361。扱う分野の広さは手元でいちばんである。百科事典
# には、サンスクリット・トルコ語・アラビア語の翻字も、数式のギリシア文字を
# 上付きと下付きで両方も、化学の平衡の矢印も、推定量を示す θ の上の山も要る。
#
# 半角フォントは 0xa121 ではなく 0xa621 から始まり、発音区別符号ごとに
# 並んでいる。母音全部にトレマ、次に母音全部にアキュート、続いてグレーブ、
# サーカムフレックス、マクロン、チルダ。1 行読めば符号が 10 個決まる。
#
# 全角フォントの最初の 7 つは文字ですらなく、電子百科事典に必要なボタンで
# ある——音声、年表、資料、画像、補注、囲み記事——そして 3,166 件の人物項目の
# 頭に置かれる顔のアイコン。
