#: 組み込みの対応表。catalog に記録されているサブブックのタイトルで引く。
BUILTIN: dict[str, GaijiTable] = {
    "リーダーズ＋プラス英和辞典": READERS_PLUS,
    "ジーニアス英和大辞典": GENIUS_DAIEIWA,
    "研究社　新英和・和英中辞典": KENKYUSHA_CHUJITEN,
    "ランダムハウス英語辞典": RANDOM_HOUSE,
    "ロングマン現代英英辞典": LONGMAN,
    "研究社新和英大辞典": KENKYUSHA_WADAI,
    "研究社　新編英和活用大辞典": COLLOC,
    "新グローバル英和・ニューセンチュリー和英": GEJCJE,
    "ジーニアス英和・和英辞典": GENIUS,
    "三省堂の英和・和英辞典": CENCRO,
    "Ｒｏｇｅｔ’ｓ": ROGET,
    "電子ブック版『日本大百科全書』": DHK01,
    "広辞苑第五版": KOJIEN_5,
    "広辞苑\u3000第四版\u3000電子ブック版": KOJIEN_4,
    "American Heritage Dictionary": AMERICAN_HERITAGE,
    "三省堂「大辞林」": DAIJIRIN,
    "改訂新版\u3000ことわざ・名言の泉": KOTOWAZA,
    "ブリタニカ小項目事典": BRITANNICA,
    "マイペディア": MYPAEDIA,
    "角川類語新辞典": RUIGO,
}


def for_subbook(subbook) -> GaijiTable:
    """``subbook`` の組み込み表を返す。なければ空の表。"""
    return dict(BUILTIN.get(subbook.title, {}))


def parse(text: str) -> GaijiTable:
    """外字の対応表ファイルを解析する。

    1 行に 1 対応。符号、空白、置き換えテキストの順。符号は ``h`` か ``z``
    （半角か全角）に 16 進 4 桁を続けたもので、整形後のテキストに現れる
    プレースホルダと同じ形である。空行と ``#`` のコメントは無視する。
    置き換えが空なら「何も出力しない」の意味になる。

        # 発音記号
        ha14c   ə
        ha177   ː
        zb121   —
    """
    table: GaijiTable = {}
    for number, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        parts = stripped.split(None, 1)
        code_text = parts[0]
        replacement = parts[1] if len(parts) > 1 else ""

        if len(code_text) != 5 or code_text[0] not in "hz":
            raise ValueError(f"line {number}: expected h/z + 4 hex digits, got {code_text!r}")
        try:
            code = int(code_text[1:], 16)
        except ValueError:
            raise ValueError(f"line {number}: {code_text!r} is not a hex code") from None

        table[(code_text[0] == "h", code)] = replacement
    return table


def load(path: str) -> GaijiTable:
    """外字の対応表ファイルを読む。"""
    with open(path, encoding="utf-8") as handle:
        return parse(handle.read())


def resolve(
    subbook,
    extra: str | GaijiTable | None = None,
    appendix=None,
) -> GaijiTable:
    """``subbook`` を整形するのに使う表を組み立てる。

    3 層あり、後のものが前のものを上書きする:

    1. ``appendix``——:class:`bkbook.appendix.Appendix`。その本が定義する
       文字すべてを ASCII で覆う。
    2. この本の組み込み表。同じことを、そのほうが読みやすいところでは
       Unicode で言う（``#e`` ではなく ``ə``）。
    3. ``extra``——呼び出し側自身の表、または対応表ファイルのパス。
    """
    table: GaijiTable = {}
    if appendix is not None:
        table.update(appendix.as_gaiji_table())
    table.update(for_subbook(subbook))
    if extra is not None:
        if isinstance(extra, (str, os.PathLike)):
            table.update(load(str(extra)))
        else:
            table.update(extra)
    return table


def format_code(narrow: bool, code: int) -> str:
    """外字の符号を、プレースホルダや対応表ファイルと同じ書き方で文字列にする。"""
    return f"{'h' if narrow else 'z'}{code:04x}"
